using System.IdentityModel.Tokens.Jwt;using EEMS.Api.Authorization;using EEMS.Api.Finance;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;
namespace EEMS.Api.Controllers;
[ApiController,Route("api/v1/elections/{electionId:guid}/finance")]public sealed class FinanceController(FinanceOperationsService service):ControllerBase{
[HttpGet,Authorize(Policy=PermissionCodes.FinanceRead)]public async Task<ActionResult<FinanceWorkspace>> Get(Guid electionId,CancellationToken ct){var x=await service.GetAsync(electionId,ct);return x is null?NotFound():Ok(x);}
[HttpPost("budgets"),Authorize(Policy=PermissionCodes.FinanceManage)]public async Task<ActionResult<BudgetSummary>> CreateBudget(Guid electionId,CreateBudgetRequest r,CancellationToken ct){var x=await service.CreateBudget(electionId,r.Name,r.Currency,ct);return x is null?BadRequest():Ok(x);}
[HttpPost("budgets/{budgetId:guid}/lines"),Authorize(Policy=PermissionCodes.FinanceManage)]public async Task<ActionResult<BudgetLineSummary>> AddLine(Guid electionId,Guid budgetId,AddBudgetLineRequest r,CancellationToken ct){var x=await service.AddLine(electionId,budgetId,r.Category,r.AllocatedAmount,ct);return x is null?BadRequest():Ok(x);}
[HttpPost("vendors"),Authorize(Policy=PermissionCodes.FinanceManage)]public async Task<ActionResult<VendorSummary>> AddVendor(Guid electionId,CreateVendorRequest r,CancellationToken ct){var x=await service.AddVendor(r.Name,r.RegistrationNumber,ct);return x is null?BadRequest():Ok(x);}
[HttpPost("expenses"),Authorize(Policy=PermissionCodes.FinanceManage)]public async Task<ActionResult<ExpenseSummary>> SubmitExpense(Guid electionId,SubmitExpenseRequest r,CancellationToken ct){if(!UserId(out var u))return Unauthorized();var x=await service.Submit(electionId,u,new(r.BudgetLineId,r.VendorId,r.InvoiceNumber,r.Amount,r.ExpenseDate),ct);return x is null?BadRequest():Ok(x);}
[HttpPost("expenses/{expenseId:guid}/decision"),Authorize(Policy=PermissionCodes.FinanceManage)]public async Task<ActionResult<ExpenseSummary>> Decide(Guid electionId,Guid expenseId,DecideExpenseRequest r,CancellationToken ct){if(!UserId(out var u))return Unauthorized();var x=await service.Decide(electionId,expenseId,u,r.StateId,r.ExpectedVersion,r.Note,ct);return x is null?Conflict():Ok(x);}
[HttpPost("expenses/{expenseId:guid}/payments"),Authorize(Policy=PermissionCodes.FinanceManage)]public async Task<ActionResult<ExpenseSummary>> Pay(Guid electionId,Guid expenseId,RecordPaymentRequest r,CancellationToken ct){if(!UserId(out var u))return Unauthorized();var x=await service.Pay(electionId,expenseId,u,r.Amount,r.Reference,ct);return x is null?BadRequest():Ok(x);}private bool UserId(out Guid x)=>Guid.TryParse(User.FindFirst(JwtRegisteredClaimNames.Sub)?.Value,out x);}
public sealed record CreateBudgetRequest(string Name,string Currency);public sealed record AddBudgetLineRequest(string Category,decimal AllocatedAmount);public sealed record CreateVendorRequest(string Name,string RegistrationNumber);public sealed record SubmitExpenseRequest(Guid BudgetLineId,Guid? VendorId,string InvoiceNumber,decimal Amount,DateOnly ExpenseDate);public sealed record DecideExpenseRequest(short StateId,int ExpectedVersion,string Note);public sealed record RecordPaymentRequest(decimal Amount,string Reference);
